<script setup lang="ts">
import{computed,ref}from 'vue';import{useQuery}from '@tanstack/vue-query';import{api}from '@/api/client';const report=ref('revenue');const from=ref('');const to=ref('');const dashboard=useQuery({queryKey:['dashboard'],queryFn:async()=>((await api.get('/reports/dashboard')).data.data??{})});const detail=useQuery({queryKey:['report',report,from,to],queryFn:async()=>((await api.get(`/reports/${report.value}`,{params:{from:from.value||undefined,to:to.value||undefined}})).data.data??{})});const metrics=computed(()=>Object.entries(dashboard.data.value??{}));const rows=computed(()=>Object.entries(detail.data.value??{}));</script>
<template><header class="page-header"><div><p class="eyebrow">ANALYTICS</p><h1>Reports</h1><p class="muted">Tenant performance and operational reporting.</p></div></header><section class="metric-grid"><article v-for="([key,value]) in metrics" :key="key" class="metric-card"><p>{{key.replaceAll('_',' ')}}</p><strong>{{value}}</strong><span>Current dashboard summary</span></article></section><section class="panel report-panel"><div class="panel-heading"><div><h2>Detailed report</h2><p class="muted">Filter the reporting period, then choose a report.</p></div></div><div class="report-filters"><select v-model="report"><option value="revenue">Revenue</option><option value="occupancy">Occupancy</option><option value="peak-hours">Peak hours</option><option value="court-utilization">Court utilization</option><option value="membership-sales">Membership sales</option><option value="coach-revenue">Coach revenue</option><option value="tournament-revenue">Tournament revenue</option><option value="rental-revenue">Rental revenue</option><option value="refunds">Refunds</option></select><input v-model="from" type="date"/><input v-model="to" type="date"/></div><div v-if="detail.isLoading.value" class="empty-state small">Loading report…</div><dl v-else class="report-data"><template v-for="([key,value]) in rows" :key="key"><dt>{{key.replaceAll('_',' ')}}</dt><dd>{{typeof value==='object'?JSON.stringify(value):value}}</dd></template></dl></section></template>
